	var image: Image = Image.create(128, 128, false, Image.FORMAT_RGBA8)
	for y in range(128):
		for x in range(128):
			var q: Vector2 = Vector2(float(x)-63.5, float(y)-63.5) / 63.5
			var alpha: float = clampf((1.0-q.length())/0.12, 0.0, 1.0) * 0.8
