	var aim := vec3(camera.get("target", [0,0,0]))
	var forward := (aim-eye).normalized()
	var right := forward.cross(vec3(camera.get("up", [0,1,0]))).normalized()
	var up := right.cross(forward).normalized()
	var nx := 2.0*(float(x)+0.5)/float(w)-1.0
	var ny := 1.0-2.0*(float(y)+0.5)/float(h)
	var half_fov := tan(deg_to_rad(float(camera.get("fov_degrees",60.0)))*0.5)
	var ray := (forward+right*nx*half_fov*float(w)/float(h)+up*ny*half_fov).normalized()
