	file.store_string(JSON.stringify(result, "\t"))
	file.close()
	print("PILOT_VERIFIED " + JSON.stringify(result))
	# Release context references before the SceneTree begins shutdown.
	targets.clear()
	call_deferred("finish_protocol")

