	hit_data = payload.duplicate(true)
	target_name = canonical_target(str(hit_data.get("target", "target_a")))
	event_id = int(hit_data.get("event_id", -1))
	event_started_s = maxf(elapsed_s, float(hit_data.get("time_s", elapsed_s)))
